(function(root){
const materialUnits=root.MaterialCore||(typeof require==='function'?require('./material-core.js'):null);
const finite=x=>typeof x==='number'&&Number.isFinite(x),norm=s=>String(s||'').toLowerCase().replaceAll('ё','е').replace(/[^\p{L}\p{N}]/gu,'');
const materialKey=l=>(l.catalogId||norm(l.name))+'|'+norm(l.unit);
function plan(state,inventory,calculate){const r=calculate(state),groups=new Map(),issues=[];for(const l of r.rows.filter(x=>x.kind==='material')){const key=materialKey(l);if(!groups.has(key))groups.set(key,{key,name:l.name,unit:l.unit,lines:[],need:0});const g=groups.get(key);g.lines.push(l);if(!finite(l.need))g.invalid=true;else g.need+=l.need;}
const rows=[...groups.values()].map(g=>{const prices=[...new Set(g.lines.map(l=>l.price))],packs=[...new Set(g.lines.map(l=>l.pack))];const stock=inventory[g.key]??0;if(!finite(stock)||stock<0)issues.push(g.name+': некорректный остаток');if(prices.length!==1||!finite(prices[0])||prices[0]<0)issues.push(g.name+': укажите одну цену для закупки во всех группах');if(packs.length!==1||!finite(packs[0])||packs[0]<=0)issues.push(g.name+': согласуйте одну закупочную кратность во всех группах');if(g.invalid)issues.push(g.name+': неизвестна потребность');const valid=!g.invalid&&prices.length===1&&finite(prices[0])&&prices[0]>=0&&packs.length===1&&finite(packs[0])&&packs[0]>0&&finite(stock)&&stock>=0;const used=valid?Math.min(g.need,stock):null,deficit=valid?Math.max(0,g.need-used):null,buy=valid?Math.ceil(deficit/packs[0]-1e-10)*packs[0]:null;return {...g,need:g.invalid?null:g.need,stock,used,deficit,buy,surplus:valid?buy-deficit:null,cash:valid?buy*prices[0]:null,price:prices[0],pack:packs[0],valid};});return {rows,issues,calculationCash:r.cash,cash:rows.reduce((a,l)=>a+(l.cash||0),0),partial:issues.length>0};}
function target(state,qty,unit,calculate){const r=calculate(state,qty);if(!finite(unit)||unit<0||r.partial)return {result:r,valid:false};const netUnit=unit/(1+state.vat/100),profit=netUnit-r.costUnit;return {result:r,valid:true,profitIncomplete:!!r.profitIncomplete,unit,netUnit,knownCostSurplus:profit,profit:r.profitIncomplete?null:profit,margin:r.profitIncomplete?null:netUnit?profit/netUnit*100:null,markup:r.profitIncomplete?null:r.costUnit?(netUnit/r.costUnit-1)*100:null,breakEven:r.profitIncomplete?null:r.costUnit*(1+state.vat/100),discount:r.unit?(1-unit/r.unit)*100:null,total:unit*qty};}
function issues(state){const a=[],add=(severity,message,index,field)=>a.push({severity,message,index,field});if(!Number.isInteger(state.qty)||state.qty<1)add('error','Партия: нужно целое положительное число',-1,'qty');for(const k of ['overhead','transport','markup','vat'])if(!finite(state[k])||state[k]<0)add('error','Некорректный процент: '+k,-1,k);if(!state.lines.length)add('error','Добавьте материалы или работы',-1,'lines');const seen=new Set();state.lines.forEach((l,index)=>{if(!l.name.trim())add('error','Не указано название позиции',index,'name');for(const [k,n] of [['qty','объём'],['price','цена'],['reserve','запас']])if(!finite(l[k])||l[k]<0)add('error',l.name+': заполните '+n,index,k);if(!finite(l.pack)||l.pack<=0)add('error',l.name+': закупочная кратность должна быть больше нуля',index,'pack');if(l.operation)OperationsCore.calculate(l.operation,state.qty).errors.forEach(e=>add('error',l.name+': '+e,index,'price'));const key=[l.catalogId||l.name,l.kind,l.group,l.scope,l.operation?l.id:''].join('|');if(seen.has(key))add('error',l.name+': повтор в одной группе',index,'group');seen.add(key);if(!l.confirmed)add('warning',l.name+': объём, запас и кратность требуют проверки',index,'confirmed');if(/Оценка по массе/.test(l.source||''))add('warning',l.name+': предварительная оценка по массе, нужна проверка ставки и марки',index,'price');if(l.price===0)add('warning',l.name+': проверьте нулевую цену',index,'price');if(l.kind==='material'&&!l.date)add('warning',l.name+': дата цены не указана',index,'date');if(/Историческая цена заказа/.test(l.source||''))add('warning',l.name+': проверьте актуальность закупочной цены и условия поставки',index,'source');});return a;}
function unitFactor(target,source,catalog){const u=s=>{const key=materialUnits.unitKey(s),types={шт:'piece',лист:'sheet',кг:'kg',т:'ton',м2:'area',м3:'volume',м:'length',л:'litre',мл:'ml'};return Object.hasOwn(types,key)?types[key]:key;};const a=u(target),b=u(source);if(a===b&&materialUnits.sameUnit(target,source))return {factor:1,reason:'Совпадают единицы цены'};if(a==='kg'&&b==='ton')return {factor:.001,reason:'1 кг = 0,001 т'};if(a==='ton'&&b==='kg')return {factor:1000,reason:'1 т = 1000 кг'};if(a==='litre'&&b==='ml')return {factor:1000,reason:'1 л = 1000 мл'};if(a==='ml'&&b==='litre')return {factor:.001,reason:'1 мл = 0,001 л'};if((a==='piece'||a==='sheet')&&catalog){const dims=catalog.name.match(/(\d+(?:[.,]\d+)?)\s*[хx×]\s*(\d+(?:[.,]\d+)?)\s*[хx×]\s*(\d+(?:[.,]\d+)?)/i);if(dims){const d=dims.slice(1).map(x=>+x.replace(',','.'));if(b==='length'&&catalog.sheet==='Пиломатериалы'&&!/^Фанера/.test(catalog.name))return {factor:d[2]/1000,reason:'Длина заготовки из наименования: '+d[2]+' мм'};if(b==='area'&&/^Фанера/.test(catalog.name))return {factor:d[1]*d[2]/1e6,reason:'Площадь одного листа из размеров, без запаса'};}}return {factor:null,reason:'Нужен явный пересчёт: единиц источника на одну единицу позиции'};}
root.ProCore={plan,target,issues,unitFactor,materialKey};if(typeof module!=='undefined')module.exports=root.ProCore;
})(typeof window!=='undefined'?window:globalThis);
